param([Parameter(Mandatory=$true)][string]$Pptx,[Parameter(Mandatory=$false)][string]$OutputJson='')
$ErrorActionPreference='Stop'
function Invoke-ComRetry([scriptblock]$Action,[int]$Attempts=20){for($i=0;$i -lt $Attempts;$i++){try{return & $Action}catch{if($_.Exception.HResult -ne -2147418111 -and $_.Exception.Message -notmatch 'rejected by callee'){throw};Start-Sleep -Milliseconds 500}};return & $Action}
function Wait-ShowView($show,[int]$Attempts=30){for($i=0;$i -lt $Attempts;$i++){try{$view=$show.View;if($null -ne $view -and ($view.PSObject.Properties.Name -contains 'State')){return $view}}catch{};Start-Sleep -Milliseconds 500};throw 'PowerPoint slideshow view was not ready.'}
$pptxPath=[IO.Path]::GetFullPath($Pptx);$pp=$null;$first=$null;$second=$null
try {
  $pp=New-Object -ComObject PowerPoint.Application;$pp.Visible=-1
  $first=$pp.Presentations.Open($pptxPath,$true,$false,$false);$firstCount=[int]$first.Slides.Count;$show1=$first.SlideShowSettings.Run();$view1=Wait-ShowView $show1
  $runningState=Invoke-ComRetry{[int]$view1.State};$runningPosition=Invoke-ComRetry{[int]$view1.CurrentShowPosition};Invoke-ComRetry{$view1.State=2};Start-Sleep -Seconds 1;$pausedState=Invoke-ComRetry{[int]$view1.State};$pausedPosition=Invoke-ComRetry{[int]$view1.CurrentShowPosition};Invoke-ComRetry{$view1.State=1};Start-Sleep -Seconds 1;$resumedState=Invoke-ComRetry{[int]$view1.State};$resumedPosition=Invoke-ComRetry{[int]$view1.CurrentShowPosition};try{Invoke-ComRetry{$view1.Exit()}}catch{};Start-Sleep -Seconds 1;try{$first.Close()}catch{}
  $second=$pp.Presentations.Open($pptxPath,$true,$false,$false);$secondCount=[int]$second.Slides.Count;$show2=$second.SlideShowSettings.Run();$view2=Wait-ShowView $show2;$replayState=Invoke-ComRetry{[int]$view2.State};$replayPosition=Invoke-ComRetry{[int]$view2.CurrentShowPosition};try{Invoke-ComRetry{$view2.Exit()}}catch{}
  if($firstCount -ne 10 -or $secondCount -ne 10){throw "Unexpected slide count during playback probe: $firstCount/$secondCount"};if($runningState -ne 1 -or $pausedState -ne 2 -or $resumedState -ne 1){throw 'PowerPoint pause/resume state transition failed.'};if($replayState -ne 1 -or $replayPosition -ne 1){throw 'PowerPoint replay did not restart at slide 1.'}
  $result=[ordered]@{ok=$true;pptx=$pptxPath;firstSlideCount=$firstCount;secondSlideCount=$secondCount;runningState=$runningState;pausedState=$pausedState;resumedState=$resumedState;runningPosition=$runningPosition;pausedPosition=$pausedPosition;resumedPosition=$resumedPosition;replayState=$replayState;replayPosition=$replayPosition;note='PowerPoint COM verified runtime start, pause, resume, and second-run replay for the ten-slide Authoring Director deck.'};$json=$result|ConvertTo-Json -Depth 4;if($OutputJson){$out=[IO.Path]::GetFullPath($OutputJson);[IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($out))|Out-Null;$json|Set-Content -LiteralPath $out -Encoding UTF8};$json
} finally {if($second){try{$second.Close()}catch{}};if($first){try{$first.Close()}catch{}};if($pp){try{$pp.Quit()}catch{}}}
